<script setup>
import { computed, onMounted, onBeforeUnmount, ref } from 'vue'
import { api, apiBaseURL } from 'boot/axios'
import { io } from 'socket.io-client'
import { useQuasar } from 'quasar'
import KitCouponInput from './KitCouponInput.vue'
import LoginMfaDialog from './LoginMfaDialog.vue'
import LicenseValidity from './LicenseValidity.vue'
import { licenseValidity } from 'src/services/license-validity'
const $q = useQuasar()
const reauthOpen=ref(false), reauthChallenge=ref(null), pendingRotation=ref(null)
const termsOpen=ref(false)
const licenseNow=ref(Date.now())
const couponCode=ref(sessionStorage.getItem('aito.kit.coupon')||'')
const data = ref(null), busy = ref(false), downloading = ref(''), visible = ref({})
const headers = () => ({ headers: { Authorization: `Bearer ${localStorage.getItem('aito_user_token') || ''}` } })
const cloudPackage=computed(()=>data.value?.downloads?.cloud || (data.value?.downloads?.render?.available?data.value.downloads.render:null))
const date=value=>value?new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—'
const money = cents => (Number(cents || 0) / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
async function load() {
  busy.value = true
  try { data.value = (await api.get('/products/aitonotify', headers())).data.data }
  catch (error) { $q.notify({ type: 'negative', message: error.response?.data?.message || 'Não foi possível carregar seus produtos.' }) }
  finally { busy.value = false }
}
async function buy() {
  busy.value = true
  try {
    const order = (await api.post('/products/aitonotify/checkout', {couponCode:couponCode.value}, headers())).data.data
    window.location.assign(order.checkoutUrl)
  } catch (error) { $q.notify({ type: 'negative', message: error.response?.data?.message || 'Não foi possível criar o checkout.' }) }
  finally { busy.value = false }
}
async function performRotate(license) { try { await api.post('/products/aitonotify/licenses/'+license._id+'/rotate',{},headers()); await load(); $q.notify({type:'positive',message:'Token anterior revogado. Atualize a instalação com o novo token.'}) } catch(error) { $q.notify({type:'negative',message:error.response?.data?.message || 'Não foi possível renovar a licença.'}) } }
async function rotate(license) {
  $q.dialog({title:'Revogar token e gerar outro',message:'O token atual deixará de funcionar nas instalações vinculadas. Para proteger sua licença, podemos solicitar uma nova validação por e-mail.',cancel:true,persistent:true}).onOk(async()=>{
    try { const token=localStorage.getItem('aito_user_token') || ''; const claims=JSON.parse(atob(token.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))); if(claims.mfa && Number(claims.mfaAt)>Date.now()/1000-300) return performRotate(license) } catch { /* The server validates the session. */ }
    try { pendingRotation.value=license; reauthChallenge.value=(await api.post('/auth/mfa/reauth',{},headers())).data; reauthOpen.value=true } catch(error) { $q.notify({type:'negative',message:error.response?.data?.message || 'Não foi possível enviar o código de confirmação.'}) }
  })
}
async function verifiedRotation(result) { localStorage.setItem('aito_user_token',result.token); localStorage.setItem('aito_user',JSON.stringify(result.user)); if(pendingRotation.value) await performRotate(pendingRotation.value); pendingRotation.value=null }
async function download(license,type='desktop') { downloading.value = license._id; try { const result=(await api.post('/products/aitonotify/download-ticket',{licenseId:license._id,package:type},headers())).data.data; window.location.assign(result.url) } catch(error) { $q.notify({type:'negative',message:error.response?.data?.message || 'Não foi possível iniciar o download. Atualize a página e tente novamente.'}) } finally { downloading.value='' } }
async function copy(token) { try { await navigator.clipboard.writeText(token); $q.notify({ type: 'positive', message: 'Token copiado.' }) } catch { $q.notify({ type: 'warning', message: 'Não foi possível copiar. Exiba o token e copie manualmente.' }) } }
let productSocket, timer, expiryTimer
onMounted(() => { expiryTimer=setInterval(()=>{licenseNow.value=Date.now()},1000); load(); const url = new URL(apiBaseURL, window.location.origin); productSocket = io(`${url.origin}/products`, { auth: { token: localStorage.getItem('aito_user_token') } }); productSocket.on('purchase.updated', load); productSocket.on('connect', load); timer = setInterval(() => { if (data.value?.orders?.some(order => order.status === 'pending')) load() }, 15000) })
onBeforeUnmount(() => { productSocket?.disconnect(); clearInterval(timer); clearInterval(expiryTimer) })
</script>
<template>
  <section class="products">
    <LoginMfaDialog v-model="reauthOpen" :challenge="reauthChallenge" @verified="verifiedRotation"/>
    <header class="products__top"><span>MINHA BIBLIOTECA</span><q-btn flat round icon="mdi-refresh" aria-label="Atualizar meus produtos" :loading="busy" @click="load"/></header>
    <div class="products__hero">
      <img src="/whatsapp-solutions/product-kit.webp" alt="Kit AitoNotify + WhatsApp BotBuilder" width="190" height="255"/>
      <div><q-badge class="products__edition" outline color="teal-3">SOFTWARE · AUTOMAÇÃO · IA</q-badge><h1>Kit AitoNotify +<br/>WhatsApp BotBuilder</h1><p>Seu software, sua marca. Atendimento, fluxos e notificações em um único kit.</p><div class="products__features"><span><q-icon name="mdi-microsoft-windows"/> Windows 10 e 11 · 64 bits</span><span><q-icon name="mdi-code-braces"/> Código-fonte personalizável</span><span><q-icon name="mdi-shield-check-outline"/> Download privado</span></div><div class="products__hero-actions"><q-btn flat no-caps dense icon="mdi-file-document-check-outline" label="Termos de uso do produto" :disable="!data?.product?.kitTerms" @click="termsOpen=true"/><a href="/politica-privacidade" target="_blank" rel="noopener">Privacidade ↗</a></div></div>
    </div>
    <div v-if="!data && busy" class="products__loading" aria-label="Carregando meus produtos"><q-skeleton dark height="240px"/></div>
    <div v-else-if="data?.licenses?.length" class="products__grid">
      <article v-for="license in data.licenses" :key="license._id" class="products__license">
        <header class="products__license-head"><div class="products__license-icon"><q-icon name="mdi-license" size="28px"/></div><div><span>ACESSO AO KIT</span><h2>Sua licença</h2></div><LicenseValidity :license="license"/></header>
        <q-banner v-if="!licenseValidity(license,licenseNow).effectiveActive" rounded class="products__license-notice">{{licenseValidity(license,licenseNow).status==='expired'?'O prazo desta licença terminou. Solicite a renovação à equipe para voltar a usar o aplicativo.':'Esta licença está suspensa. Fale com a equipe para revisar o acesso.'}}</q-banner>
        <div class="products__workspace">
          <section class="products__activation"><h3><q-icon name="mdi-key-outline"/> Ative sua instalação</h3><p>Copie a chave e cole no assistente de configuração do Desktop ou Cloud.</p><div class="products__token"><code>{{ visible[license._id] ? license.token : '••••••••••••••••••••••••' }}</code><q-btn flat round dense :icon="visible[license._id] ? 'mdi-eye-off-outline' : 'mdi-eye-outline'" :aria-label="visible[license._id]?'Ocultar chave da licença':'Mostrar chave da licença'" @click="visible[license._id] = !visible[license._id]"/><q-btn flat round dense icon="mdi-content-copy" aria-label="Copiar chave da licença" @click="copy(license.token)"/></div><small>Uma instalação ativa por licença. Mantenha a chave em segurança.</small><q-btn flat no-caps dense color="orange-3" label="Substituir chave de acesso" icon="mdi-key-change" :disable="!licenseValidity(license,licenseNow).effectiveActive" @click="rotate(license)"/><small class="products__rotation">Use em caso de vazamento. A chave anterior será revogada.</small></section>
          <section class="products__downloads"><h3><q-icon name="mdi-download-outline"/> Instale do seu jeito</h3><div class="products__download-card"><q-icon name="mdi-microsoft-windows" size="30px"/><div><strong>Aplicativo Desktop</strong><small>Instalador Windows · pronto para configurar</small><small v-if="data.downloads?.desktop">v{{data.downloads.desktop.version}} · {{(data.downloads.desktop.size/1024/1024).toFixed(1)}} MB</small></div><q-btn unelevated no-caps color="teal-7" icon="mdi-download" :label="data.downloads?.desktop?'Baixar':'Em breve'" :disable="!licenseValidity(license,licenseNow).effectiveActive || !data.downloads?.desktop" :loading="downloading===license._id" @click="download(license)"/></div><div class="products__download-card"><q-icon name="mdi-cloud-code-outline" size="30px"/><div><strong>Código-fonte · Cloud</strong><small>Personalize e publique no Render</small><small v-if="cloudPackage">v{{cloudPackage.version}} · {{(cloudPackage.size/1024/1024).toFixed(1)}} MB</small></div><q-btn outline no-caps color="teal-3" icon="mdi-download" :label="cloudPackage?'Baixar':'Em breve'" :disable="!licenseValidity(license,licenseNow).effectiveActive || !cloudPackage" :loading="downloading===license._id" @click="download(license,'cloud')"/></div><a v-if="data.product.tutorialUrl" class="products__help" :href="data.product.tutorialUrl" target="_blank" rel="noopener noreferrer"><q-icon name="mdi-play-circle-outline"/> Primeiros passos e ajuda <q-icon name="mdi-arrow-top-right"/></a></section>
        </div>
        <q-expansion-item class="products__details" dense icon="mdi-information-outline" label="Detalhes da licença e versões"><div><p>Origem: {{license.ownerType==='whatsapp'?'Compra pelo WhatsApp':license.sourceId?.startsWith('admin-grant:')?'Acesso liberado pela equipe':'Compra pelo site'}} · {{date(license.issuedAt||license.createdAt)}}</p><small v-if="data.downloads?.desktop">Desktop: {{data.downloads.desktop.filename}}</small><small v-if="cloudPackage">Cloud: {{cloudPackage.filename}}</small><p v-if="data.downloads?.desktop?.notes" class="products__release-notes">{{data.downloads.desktop.notes}}</p><p v-if="cloudPackage?.notes" class="products__release-notes">{{cloudPackage.notes}}</p></div></q-expansion-item>
      </article>
    </div>
    <article v-else-if="data" class="products__offer"><h2>Seu próximo passo: automatizar.</h2><p>Adquira o kit com o aplicativo Desktop e o código-fonte para adaptar à sua marca.</p><strong v-if="data.product?.priceCents != null"><template v-if="data.product.originalPriceCents > data.product.priceCents">De {{ money(data.product.originalPriceCents) }} por </template>{{ money(data.product.priceCents) }}</strong><KitCouponInput v-model="couponCode" dark/><q-btn unelevated no-caps color="teal-7" icon="mdi-cart-outline" label="Comprar o kit com InfinitePay" :loading="busy" :disable="!data.product?.available" @click="buy"/><small>O produto é liberado após a confirmação do pagamento.</small></article>
    <q-expansion-item v-if="data?.orders?.length" icon="mdi-receipt-text-clock-outline" label="Histórico de compras" class="products__history"><div v-for="order in data.orders" :key="order._id||order.orderNsu" class="products__order"><div><strong>{{money(order.amountCents)}}</strong><span>{{date(order.paidAt||order.createdAt)}}</span><code>{{order.orderNsu}}</code></div><q-badge :color="order.status==='paid'?'teal-7':'orange-9'" :label="order.status==='paid'?'Pagamento confirmado':'Aguardando pagamento'"/><a v-if="order.receiptUrl" :href="order.receiptUrl" target="_blank" rel="noopener noreferrer">Comprovante ↗</a></div></q-expansion-item>
    <p v-if="data?.orders?.some(order => order.status === 'pending')" class="products__pending">Pagamento em análise. Se concluiu o checkout, atualize esta tela em alguns instantes.</p>
    <q-dialog v-model="termsOpen"><q-card class="products-terms"><q-card-section class="products-terms__head"><div><small>VERSÃO {{data?.product?.kitTerms?.version}}</small><h2>{{data?.product?.kitTerms?.title}}</h2></div><q-btn flat round dense icon="mdi-close" aria-label="Fechar termos de uso" v-close-popup/></q-card-section><q-separator dark/><q-card-section class="products-terms__content">{{data?.product?.kitTerms?.content}}</q-card-section><q-separator dark/><q-card-actions align="right"><q-btn unelevated no-caps color="teal-7" label="Fechar" v-close-popup/></q-card-actions></q-card></q-dialog>
  </section>
</template>
<style scoped>
.products{color:#effffb}.products__top{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.products__top>span,.products__license-head>div>span{color:#8fffee;font-size:10px;font-weight:800;letter-spacing:.16em}.products__hero{display:grid;grid-template-columns:190px minmax(0,1fr);align-items:center;gap:35px;margin-bottom:32px;padding:24px;border:1px solid #2a6358;border-radius:22px;background:radial-gradient(ellipse at 10% 50%,#0c535344,transparent 65%),linear-gradient(135deg,#082725,#061819)}.products__hero>img{width:100%;height:255px;object-fit:contain;filter:drop-shadow(0 12px 22px #0009)}.products__hero h1{font-size:clamp(23px,3vw,37px);font-weight:800;line-height:1.2;margin:12px 0;color:#f0fffa}.products__hero p{margin:12px 0;line-height:1.7;color:#b1d4cb;max-width:none}.products__edition{font-size:9px;letter-spacing:.09em}.products__features{display:flex;flex-wrap:wrap;gap:9px 18px;margin-top:20px}.products__features>span{display:flex;gap:7px;align-items:center;color:#c9e9dd;font-size:11px}.products__features .q-icon{font-size:19px;color:#7ce4ce}.products__hero-actions{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-top:20px}.products__hero-actions .q-btn{color:#98e8d7;font-size:11px}.products a{color:#93e8d7}.products__hero-actions>a{font-size:11px}.products__grid{display:grid;gap:20px}.products__license{overflow:hidden;border:1px solid #2e5e52;border-radius:18px;background:#071e1f}.products__license-head{display:flex;gap:13px;align-items:center;flex-wrap:wrap;padding:22px;border-bottom:1px solid #244b42;background:#0c2b27}.products__license-icon{display:grid;place-items:center;background:#144b3d;color:#9cf5d5;width:48px;height:48px;border-radius:13px}.products__license-head>div:nth-child(2){flex:1}.products__license-head h2{font-size:21px;line-height:1.3;margin:3px 0 0;color:#f0fff7}.products__workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px;padding:25px}.products__workspace h3{display:flex;align-items:center;gap:8px;font-size:15px;line-height:1.5;margin:0 0 13px;color:#e8fff4}.products__workspace p{font-size:12px;line-height:1.8;color:#adcbc1;margin:0 0 14px}.products__activation>small{display:block;font-size:11px;line-height:1.7;color:#9dbfb1;margin:12px 0}.products__activation>.q-btn{margin-top:12px;font-size:11px}.products__activation>.products__rotation{margin-top:3px;color:#a4afa8;font-size:10px}.products__token{display:flex;align-items:center;gap:2px;min-width:0;padding:8px;border:1px solid #315e4e;border-radius:9px;background:#02110d}.products__token code{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;font-size:12px;color:#c6f8e6}.products__token .q-btn{color:#97d9bf}.products__download-card{display:flex;align-items:center;gap:12px;padding:15px 12px;border:1px solid #31594d;border-radius:12px;margin-bottom:10px;background:#0b2925}.products__download-card>.q-icon{color:#93dbc6}.products__download-card>div{flex:1;min-width:0}.products__download-card strong,.products__download-card small{display:block}.products__download-card strong{font-size:13px;color:#e6fff5;line-height:1.5}.products__download-card small{font-size:10px;line-height:1.8;color:#a5c7b8}.products__download-card .q-btn{font-size:11px;min-height:36px}.products__help{display:flex;align-items:center;gap:7px;font-size:11px;padding:10px 0;text-decoration:none}.products__help .q-icon{font-size:19px}.products__details{border-top:1px solid #23483d;color:#a5c7b7;font-size:12px}.products__details :deep(.q-item){min-height:45px}.products__details>div,.products__details :deep(.q-expansion-item__content)>div{padding:0 22px 16px}.products__details small{display:block;overflow-wrap:anywhere;font-size:10px;line-height:1.8}.products__details p{font-size:11px;line-height:1.8;color:#a5c7b7}.products__license-notice{margin:16px 22px 0;background:#4a3d255c;color:#f4dbb2;font-size:12px;line-height:1.8;border:1px solid #796239}.products__offer{display:grid;justify-items:start;gap:12px;padding:26px;border:1px solid #2d5c4b;border-radius:18px;background:#0a2723}.products__offer h2{font-size:25px;line-height:1.3;margin:0}.products__offer p{font-size:13px;line-height:1.8;color:#b1cebd;margin:0}.products__offer strong{font-size:24px;color:#9eeaca}.products__offer small{color:#a4b9ad;font-size:11px}.products__history{margin-top:25px;border:1px solid #315b4d;border-radius:15px;overflow:hidden}.products__order{display:flex;align-items:center;gap:14px;padding:18px;border-top:1px solid #23483b}.products__order>div{flex:1;min-width:0}.products__order strong,.products__order span,.products__order code{display:block;line-height:1.8}.products__order strong{font-size:15px}.products__order span,.products__order a{font-size:11px;color:#aac9b9}.products__order code{font-size:10px;overflow-wrap:anywhere;color:#8caf9b}.products__release-notes{white-space:pre-wrap;font-size:11px;line-height:1.8}.products__pending{font-size:12px;line-height:1.8;color:#b7d1bf}.products-terms{width:760px;max-width:calc(100vw - 24px);max-height:90dvh;display:flex;flex-direction:column;border:1px solid #3b7561;border-radius:18px;background:#071c1c;color:#edfdf7}.products-terms__head{display:flex;gap:15px;align-items:flex-start}.products-terms__head>div{flex:1}.products-terms__head small{color:#9cd6bb;font-size:10px;letter-spacing:.1em}.products-terms__head h2{font-size:21px;line-height:1.4;margin:7px 0 0}.products-terms__content{white-space:pre-wrap;overflow-y:auto;line-height:1.9;font-size:13px;color:#c0dacd}.products-terms .q-card__actions{flex:none}.products__loading{margin:20px 0}@media(max-width:800px){.products__workspace{grid-template-columns:1fr;gap:24px}.products__activation{padding-bottom:23px;border-bottom:1px solid #264b40}}@media(max-width:600px){.products__hero{grid-template-columns:95px minmax(0,1fr);gap:15px;padding:18px 14px}.products__hero>img{height:155px;align-self:start}.products__hero h1{font-size:21px}.products__hero p{font-size:12px}.products__features,.products__hero-actions{grid-column:1/-1}.products__features{gap:10px;margin-top:14px}.products__features>span{font-size:10px}.products__hero-actions{gap:7px}.products__hero-actions .q-btn{font-size:10px}.products__edition{font-size:8px}.products__workspace{padding:18px}.products__license-head{padding:18px}.products__license-head :deep(.license-validity){width:100%}.products__download-card{flex-wrap:wrap}.products__download-card>.q-btn{width:100%}.products__download-card>div{flex-basis:calc(100% - 48px)}.products__order{flex-wrap:wrap}.products__order>div{flex-basis:100%}.products-terms__head h2{font-size:18px}.products__offer{padding:20px}}
